{"command":"cat > jv.cpp << 'EOF'
#include <bits/stdc++.h>
using namespace std;

// Jonker-Volgenant from CP-algorithms
// returns col_of_row (0-based)
vector<int> assignment(const vector<vector<double>>& a) {
    int n = (int)a.size();
    vector<double> u(n + 1), v(n + 1);
    vector<int> p(n + 1), way(n + 1);
    const double INF = 1e100;
    for (int i = 1; i <= n; ++i) {
        p[0] = i;
        int j0 = 0;
        vector<double> minv(n + 1, INF);
        vector<char> used(n + 1, false);
        do {
            used[j0] = true;
            int i0 = p[j0], j1 = 0;
            double delta = INF;
            for (int j = 1; j <= n; ++j) if (!used[j]) {
                double cur = a[i0 - 1][j - 1] - u[i0] - v[j];
                if (cur < minv[j]) {
                    minv[j] = cur;
                    way[j] = j0;
                }
                if (minv[j] < delta) {
                    delta = minv[j];
                    j1 = j;
                }
            }
            for (int j = 0; j <= n; ++j) {
                if (used[j]) {
                    u[p[j]] += delta;
                    v[j] -= delta;
                } else {
                    minv[j] -= delta;
                }
            }
            j0 = j1;
        } while (p[j0] != 0);
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0);
    }
    vector<int> col(n);
    for (int j = 1; j <= n; ++j) col[p[j] - 1] = j - 1;
    return col;
}

int main() {
    int n = 600;
    vector<vector<double>> a(n, vector<double>(n));
    mt19937 rng(1);
    uniform_real_distribution<double> dist(0.0, 1.0);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            a[i][j] = dist(rng);
    auto t0 = chrono::high_resolution_clock::now();
    auto col = assignment(a);
    auto t1 = chrono::high_resolution_clock::now();
    double cost = 0;
    for (int i = 0; i < n; i++) cost += a[i][col[i]];
    cout << "time " << chrono::duration<double>(t1 - t0).count() << " cost " << cost << "\n";
}
