#include <vector>
#include <random>
#include <chrono>
#include <iostream>
#include <cmath>
#include <algorithm>
#include <cstdint>
using namespace std;

// Sparse JV: each row has a list of (col, cost). Missing edges are forbidden (INF).
// If no perfect matching in the sparse graph, this may infinite-loop; caller must ensure feasibility
// by including a matching (e.g. greedy) or all edges. We'll add a fallback large cost? No, caller provides edges.

struct Edge { int j; double c; };

vector<int> assignment_sparse(int n, const vector<vector<Edge>>& rows) {
    vector<double> u(n + 1), v(n + 1);
    vector<int> p(n + 1, 0), way(n + 1, 0);
    const double INF = 1e100;
    vector<double> minv(n + 1);
    vector<char> used(n + 1);
    // For columns not in the row's adjacency, reduced cost is INF - u - v which is still INF-ish.
    // To keep JV correct we must consider all columns OR know missing are forbidden.
    // Forbidden edges: treat as INF. The inner loop still needs all columns for correctness of duals
    // if some columns are only reachable via forbidden... For a feasible sparse instance, columns
    // not adjacent have INF reduced cost and won't be chosen if a finite matching exists.
    // But we still scan all columns unless we track candidates.
    // Optimization: maintain a list of columns with finite minv, initially the row's neighbors.
    // When we scan a matched row, we only look at its neighbors.

    for (int i = 1; i <= n; ++i) {
        p[0] = i;
        int j0 = 0;
        for (int j = 0; j <= n; ++j) minv[j] = INF;
        fill(used.begin(), used.end(), 0);
        // active columns that have been given a finite minv
        vector<int> active;
        active.reserve(256);
        auto relax_row = [&](int i0, int from_j) {
            // i0 is 1-based row
            double ui = u[i0];
            for (const auto& e : rows[i0 - 1]) {
                int j = e.j + 1;
                if (used[j]) continue;
                double cur = e.c - ui - v[j];
                if (cur < minv[j]) {
                    if (minv[j] >= INF/2) active.push_back(j);
                    minv[j] = cur;
                    way[j] = from_j;
                }
            }
        };
        relax_row(i, 0);
        int guard = 0;
        do {
            used[j0] = true;
            int i0 = p[j0];
            if (j0 != 0) {
                // row matched to j0 can offer its edges
                relax_row(i0, j0);
            }
            double delta = INF;
            int j1 = 0;
            // scan active
            for (int j : active) {
                if (used[j]) continue;
                if (minv[j] < delta) {
                    delta = minv[j];
                    j1 = j;
                }
            }
            if (j1 == 0) {
                // no finite augmenting path
                cerr << "no path at row " << i << "\n";
                return {};
            }
            for (int j = 0; j <= n; ++j) {
                if (used[j]) {
                    u[p[j]] += delta;
                    v[j] -= delta;
                } else if (minv[j] < INF/2) {
                    minv[j] -= delta;
                }
            }
            j0 = j1;
            if (++guard > n * n) {
                cerr << "guard\n";
                return {};
            }
        } while (p[j0] != 0);
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0);
    }
    vector<int> col(n);
    for (int j = 1; j <= n; ++j) col[p[j] - 1] = j - 1;
    return col;
}

int main() {
    // synthetic: each row connected to k random cols + a planted permutation to ensure feasibility
    int n = 600;
    int k = 32;
    mt19937 rng(1);
    uniform_int_distribution<int> coli(0, n - 1);
    uniform_real_distribution<double> cd(0.0, 1.0);
    vector<int> plant(n);
    iota(plant.begin(), plant.end(), 0);
    shuffle(plant.begin(), plant.end(), rng);
    vector<vector<Edge>> rows(n);
    for (int i = 0; i < n; i++) {
        vector<char> seen(n, 0);
        rows[i].push_back({plant[i], cd(rng)});
        seen[plant[i]] = 1;
        while ((int)rows[i].size() < k) {
            int j = coli(rng);
            if (seen[j]) continue;
            seen[j] = 1;
            rows[i].push_back({j, cd(rng)});
        }
    }
    auto t0 = chrono::high_resolution_clock::now();
    auto col = assignment_sparse(n, rows);
    auto t1 = chrono::high_resolution_clock::now();
    cout << "time " << chrono::duration<double>(t1-t0).count() << " ok " << (!col.empty()) << "\n";
}
