#include <vector>
#include <random>
#include <chrono>
#include <iostream>
#include <algorithm>
#include <cstdint>
using namespace std;

struct Edge { int j; double c; };

// Column-centric adjacency too, for scanning matched rows' edges only.
// JV shortest augmenting path restricted to sparse edges.

vector<int> assignment_sparse(int n, const vector<vector<Edge>>& rows) {
    const double INF = 1e100;
    vector<double> u(n), v(n, 0.0);
    vector<int> row_of_col(n, -1), col_of_row(n, -1);
    vector<double> dist(n);
    vector<int> pred_row(n);
    vector<char> seen(n);

    // flat column index of edges for faster scan: already vector

    for (int i = 0; i < n; ++i) {
        // init dijkstra labels from free row i
        for (int j = 0; j < n; ++j) {
            dist[j] = INF;
            seen[j] = 0;
        }
        for (const auto& e : rows[i]) {
            double rc = e.c - u[i] - v[e.j];
            if (rc < dist[e.j]) {
                dist[e.j] = rc;
                pred_row[e.j] = i;
            }
        }
        int jmin = -1;
        double dmin = INF;
        int scanned = 0;
        while (scanned < n) {
            jmin = -1;
            dmin = INF;
            for (int j = 0; j < n; ++j) {
                if (!seen[j] && dist[j] < dmin) {
                    dmin = dist[j];
                    jmin = j;
                }
            }
            if (jmin < 0 || dmin >= INF/2) {
                cerr << "no path row " << i << "\n";
                return {};
            }
            seen[jmin] = 1;
            scanned++;
            int r = row_of_col[jmin];
            if (r < 0) break;
            // relax edges of row r
            double base = dmin; // dist to this column; matching edge rc = 0 so dist to row r = dmin
            double ur = u[r];
            for (const auto& e : rows[r]) {
                int j = e.j;
                if (seen[j]) continue;
                double nd = base + e.c - ur - v[j];
                if (nd < dist[j]) {
                    dist[j] = nd;
                    pred_row[j] = r;
                }
            }
        }
        // augment
        int j = jmin;
        while (true) {
            int pr = pred_row[j];
            int old = col_of_row[pr];
            col_of_row[pr] = j;
            row_of_col[j] = pr;
            if (pr == i) break;
            j = old;
        }
        // dual update: v[j] += dist[j] - dmin for seen; then u from assignment
        for (int j = 0; j < n; ++j) if (seen[j]) v[j] += dist[j] - dmin;
        for (int r = 0; r <= i; ++r) {
            int c = col_of_row[r];
            // u[r] = C[r,c] - v[c]. Need the cost of the matched edge.
            double cij = 0;
            bool found = false;
            for (const auto& e : rows[r]) if (e.j == c) { cij = e.c; found = true; break; }
            if (!found) { cerr << "matched missing edge\n"; return {}; }
            u[r] = cij - v[c];
        }
    }
    return col_of_row;
}

int main() {
    int n = 600, k = 32;
    mt19937 rng(1);
    uniform_int_distribution<int> coli(0, n - 1);
    uniform_real_distribution<double> cd(0.0, 1.5);
    vector<int> plant(n);
    iota(plant.begin(), plant.end(), 0);
    shuffle(plant.begin(), plant.end(), rng);
    vector<vector<Edge>> rows(n);
    for (int i = 0; i < n; i++) {
        vector<char> seen(n, 0);
        rows[i].push_back({plant[i], cd(rng)});
        seen[plant[i]] = 1;
        while ((int)rows[i].size() < k) {
            int j = coli(rng);
            if (seen[j]) continue;
            seen[j] = 1;
            rows[i].push_back({j, cd(rng)});
        }
    }
    auto t0 = chrono::high_resolution_clock::now();
    auto col = assignment_sparse(n, rows);
    auto t1 = chrono::high_resolution_clock::now();
    double cost = 0;
    for (int i = 0; i < n; i++) {
        for (auto& e : rows[i]) if (e.j == col[i]) cost += e.c;
    }
    cout << "time " << chrono::duration<double>(t1-t0).count() << " cost " << cost << " ok " << (!col.empty()) << "\n";
}
