#include <vector>
#include <random>
#include <chrono>
#include <iostream>
#include <algorithm>
#include <queue>
#include <cstdint>
using namespace std;

struct Edge { int j; double c; };

vector<int> assignment_sparse(int n, const vector<vector<Edge>>& rows) {
    const double INF = 1e100;
    vector<double> u(n, 0.0), v(n, 0.0);
    vector<int> row_of_col(n, -1), col_of_row(n, -1);
    vector<double> dist(n);
    vector<int> pred_row(n);
    vector<char> seen(n);
    // cost lookup of matched edges: store matched cost
    vector<double> match_cost(n);

    using Node = pair<double, int>;
    priority_queue<Node, vector<Node>, greater<Node>> pq;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            dist[j] = INF;
            seen[j] = 0;
        }
        pq = priority_queue<Node, vector<Node>, greater<Node>>();
        for (const auto& e : rows[i]) {
            double rc = e.c - u[i] - v[e.j];
            if (rc < dist[e.j]) {
                dist[e.j] = rc;
                pred_row[e.j] = i;
                pq.emplace(rc, e.j);
            }
        }
        int jmin = -1;
        double dmin = INF;
        while (!pq.empty()) {
            auto [d, j] = pq.top();
            pq.pop();
            if (seen[j] || d > dist[j] + 1e-12) continue;
            seen[j] = 1;
            int r = row_of_col[j];
            if (r < 0) {
                jmin = j;
                dmin = d;
                break;
            }
            double ur = u[r];
            for (const auto& e : rows[r]) {
                int jj = e.j;
                if (seen[jj]) continue;
                double nd = d + e.c - ur - v[jj];
                if (nd < dist[jj]) {
                    dist[jj] = nd;
                    pred_row[jj] = r;
                    pq.emplace(nd, jj);
                }
            }
        }
        if (jmin < 0) {
            cerr << "no path " << i << "\n";
            return {};
        }
        int j = jmin;
        while (true) {
            int pr = pred_row[j];
            int old = col_of_row[pr];
            col_of_row[pr] = j;
            row_of_col[j] = pr;
            // find cost
            double cij = 0;
            for (const auto& e : rows[pr]) if (e.j == j) { cij = e.c; break; }
            match_cost[pr] = cij;
            if (pr == i) break;
            j = old;
        }
        for (int jj = 0; jj < n; ++jj) if (seen[jj]) v[jj] += dist[jj] - dmin;
        for (int r = 0; r <= i; ++r) {
            u[r] = match_cost[r] - v[col_of_row[r]];
        }
    }
    return col_of_row;
}

int main() {
    int n = 600, k = 48;
    mt19937 rng(1);
    uniform_int_distribution<int> coli(0, n - 1);
    uniform_real_distribution<double> cd(0.0, 1.5);
    vector<int> plant(n);
    iota(plant.begin(), plant.end(), 0);
    shuffle(plant.begin(), plant.end(), rng);
    vector<vector<Edge>> rows(n);
    for (int i = 0; i < n; i++) {
        vector<char> seen(n, 0);
        rows[i].push_back({plant[i], cd(rng) * 0.01}); // cheap planted? no, random
        seen[plant[i]] = 1;
        rows[i][0].c = cd(rng);
        while ((int)rows[i].size() < k) {
            int j = coli(rng);
            if (seen[j]) continue;
            seen[j] = 1;
            rows[i].push_back({j, cd(rng)});
        }
    }
    auto t0 = chrono::high_resolution_clock::now();
    auto col = assignment_sparse(n, rows);
    auto t1 = chrono::high_resolution_clock::now();
    cout << "time " << chrono::duration<double>(t1-t0).count() << " ok " << (!col.empty()) << "\n";
}
