{"command":"cat > bench_sparse.py << 'EOF'
import time
import numpy as np
from scipy.spatial import cKDTree
from scipy.optimize import linear_sum_assignment
import ot

# load C++ via a simple file protocol: write edges, run binary? better ctypes later.
# For now time python graph build + estimate solver by calling compiled binary through stdin.

import subprocess, struct, os

def build_and_time(n=600, seed=1, R=0.5):
    np.random.seed(seed)
    sp = np.random.rand(n, 2)
    tp = np.random.rand(n, 2)
    t0 = time.perf_counter()
    tree = cKDTree(tp)
    neigh = tree.query_ball_point(sp, R, workers=1)
    # compute costs
    edges_i = []
    edges_j = []
    edges_c = []
    for i, js in enumerate(neigh):
        if not js:
            continue
        js = np.asarray(js, dtype=np.int32)
        d = tp[js] - sp[i]
        c = np.sqrt((d*d).sum(-1))
        edges_i.append(np.full(len(js), i, dtype=np.int32))
        edges_j.append(js)
        edges_c.append(c.astype(np.float64))
    ei = np.concatenate(edges_i)
    ej = np.concatenate(edges_j)
    ec = np.concatenate(edges_c)
    t1 = time.perf_counter()
    print(f'build {t1-t0:.4f} edges {len(ec)} mean {len(ec)/n:.1f}')
    return ei, ej, ec, sp, tp

# Write a C++ solver that reads n, m, then edges from a npy-like raw file
open('solver_main.cpp','w').write(r'''
#include <vector>
#include <chrono>
#include <iostream>
#include <queue>
#include <cstdint>
#include <cstring>
#include <cstdio>
using namespace std;

struct Edge { int j; double c; };

vector<int> assignment_sparse(int n, const vector<vector<Edge>>& rows) {
    const double INF = 1e100;
    vector<double> u(n, 0.0), v(n, 0.0);
    vector<int> row_of_col(n, -1), col_of_row(n, -1);
    vector<double> dist(n);
    vector<int> pred_row(n);
    vector<char> seen(n);
    vector<double> match_cost(n, 0.0);
    using Node = pair<double, int>;
    vector<Node> heap;
    heap.reserve(n * 8);

    auto heap_push = [&](double d, int j) {
        heap.emplace_back(d, j);
        push_heap(heap.begin(), heap.end(), greater<Node>());
    };
    auto heap_pop = [&]() {
        pop_heap(heap.begin(), heap.end(), greater<Node>());
        Node x = heap.back();
        heap.pop_back();
        return x;
    };

    for (int i = 0; i < n; ++i) {
        fill(dist.begin(), dist.end(), INF);
        fill(seen.begin(), seen.end(), 0);
        heap.clear();
        for (const auto& e : rows[i]) {
            double rc = e.c - u[i] - v[e.j];
            if (rc < dist[e.j]) {
                dist[e.j] = rc;
                pred_row[e.j] = i;
                heap_push(rc, e.j);
            }
        }
        int jmin = -1;
        double dmin = INF;
        while (!heap.empty()) {
            auto [d, j] = heap_pop();
            if (seen[j] || d > dist[j] + 1e-15) continue;
            seen[j] = 1;
            int r = row_of_col[j];
            if (r < 0) { jmin = j; dmin = d; break; }
            double ur = u[r];
            for (const auto& e : rows[r]) {
                int jj = e.j;
                if (seen[jj]) continue;
                double nd = d + e.c - ur - v[jj];
                if (nd < dist[jj]) {
                    dist[jj] = nd;
                    pred_row[jj] = r;
                    heap_push(nd, jj);
                }
            }
        }
        if (jmin < 0) return {};
        int j = jmin;
        while (true) {
            int pr = pred_row[j];
            int old = col_of_row[pr];
            col_of_row[pr] = j;
            row_of_col[j] = pr;
            double cij = 0;
            for (const auto& e : rows[pr]) if (e.j == j) { cij = e.c; break; }
            match_cost[pr] = cij;
            if (pr == i) break;
            j = old;
        }
        for (int jj = 0; jj < n; ++jj) if (seen[jj]) v[jj] += dist[jj] - dmin;
        for (int r = 0; r <= i; ++r) u[r] = match_cost[r] - v[col_of_row[r]];
    }
    return col_of_row;
}

int main() {
    int n, m;
    if (fread(&n, 4, 1, stdin) != 1) return 1;
    if (fread(&m, 4, 1, stdin) != 1) return 1;
    vector<int> ei(m), ej(m);
    vector<double> ec(m);
    if (fread(ei.data(), 4, m, stdin) != (size_t)m) return 1;
    if (fread(ej.data(), 4, m, stdin) != (size_t)m) return 1;
    if (fread(ec.data(), 8, m, stdin) != (size_t)m) return 1;
    vector<vector<Edge>> rows(n);
    for (int k = 0; k < m; k++) rows[ei[k]].push_back({ej[k], ec[k]});
    auto t0 = chrono::high_resolution_clock::now();
