// Build radius graph from points and solve.
// points are float64 C-contiguous n x 2.
static PyObject* solve_points(PyObject* self, PyObject* args) {
    PyObject* sp_obj;
    PyObject* tp_obj;
    double radius;
    if (!PyArg_ParseTuple(args, "OOd", &sp_obj, &tp_obj, &radius)) return NULL;
    Py_buffer sp_buf, tp_buf;
    if (PyObject_GetBuffer(sp_obj, &sp_buf, PyBUF_SIMPLE) != 0) return NULL;
    if (PyObject_GetBuffer(tp_obj, &tp_buf, PyBUF_SIMPLE) != 0) { PyBuffer_Release(&sp_buf); return NULL; }
    int n = (int)(sp_buf.len / (2 * sizeof(double)));
    const double* sp = (const double*)sp_buf.buf;
    const double* tp = (const double*)tp_buf.buf;
    double R2 = radius * radius;

    // Grid hash for 2D unit square
    double cell = radius;
    if (cell < 1e-6) cell = 1e-6;
    int g = (int)std::ceil(1.0 / cell) + 1;
    if (g < 1) g = 1;
    std::vector<std::vector<int>> bins(g * g);
    auto bidx = [&](double x, double y) {
        int ix = (int)(x / cell);
        int iy = (int)(y / cell);
        if (ix < 0) ix = 0; if (ix >= g) ix = g - 1;
        if (iy < 0) iy = 0; if (iy >= g) iy = g - 1;
        return iy * g + ix;
    };
    for (int j = 0; j < n; ++j) {
        bins[bidx(tp[2*j], tp[2*j+1])].push_back(j);
    }

    std::vector<std::vector<Edge>> rows(n);
    for (int i = 0; i < n; ++i) {
        double x = sp[2*i], y = sp[2*i+1];
        int ix = (int)(x / cell);
        int iy = (int)(y / cell);
        if (ix < 0) ix = 0; if (ix >= g) ix = g - 1;
        if (iy < 0) iy = 0; if (iy >= g) iy = g - 1;
        rows[i].reserve(64);
        for (int dy = -1; dy <= 1; ++dy) {
            int yy = iy + dy;
            if (yy < 0 || yy >= g) continue;
            for (int dx = -1; dx <= 1; ++dx) {
                int xx = ix + dx;
                if (xx < 0 || xx >= g) continue;
                const auto& bin = bins[yy * g + xx];
                for (int j : bin) {
                    double dx_ = tp[2*j] - x;
                    double dy_ = tp[2*j+1] - y;
                    double d2 = dx_*dx_ + dy_*dy_;
                    if (d2 <= R2) {
                        rows[i].push_back({j, std::sqrt(d2)});
                    }
                }
            }
        }
    }
    auto col = assignment_sparse(n, rows);
    PyBuffer_Release(&tp_buf);
    PyBuffer_Release(&sp_buf);
    if ((int)col.size() != n) {
        Py_RETURN_NONE;
    }
    PyObject* out = PyBytes_FromStringAndSize(nullptr, n * sizeof(int32_t));
    if (!out) return NULL;
    memcpy(PyBytes_AS_STRING(out), col.data(), n * sizeof(int32_t));
    return out;
}

