#include <Python.h>
#include <vector>
#include <algorithm>
#include <cstdint>
#include <cstring>
#include <cmath>

// Integer-cost Jonker-Volgenant on a dense matrix stored as int32, but we only
// need a fast dense baseline. Also sparse version with bucket queue.

struct Edge { int j; int c; };

static std::vector<int> sap_sparse(int n, const std::vector<std::vector<Edge>>& rows) {
    const int INF = 0x3fffffff;
    std::vector<int> u(n, 0), v(n, 0);
    std::vector<int> row_of_col(n, -1), col_of_row(n, -1);
    std::vector<int> dist(n), pred(n);
    std::vector<char> seen(n);
    std::vector<int> match_cost(n, 0);

    // Dial buckets. Reduced costs nonnegative. Max cost ~ 2e9 if we scale badly.
    // Use binary heap of pairs for robustness; optimize later.
    using Node = std::pair<int, int>;
    std::vector<Node> heap;
    heap.reserve(n * 4);

    for (int i = 0; i < n; ++i) {
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(seen.begin(), seen.end(), 0);
        heap.clear();
        int ui = u[i];
        for (auto& e : rows[i]) {
            int rc = e.c - ui - v[e.j];
            if (rc < dist[e.j]) {
                dist[e.j] = rc;
                pred[e.j] = i;
                heap.emplace_back(rc, e.j);
                std::push_heap(heap.begin(), heap.end(), std::greater<Node>());
            }
        }
        int jmin = -1, dmin = INF;
        while (!heap.empty()) {
            std::pop_heap(heap.begin(), heap.end(), std::greater<Node>());
            auto [d, j] = heap.back();
            heap.pop_back();
            if (seen[j] || d != dist[j]) continue;
            seen[j] = 1;
            int r = row_of_col[j];
            if (r < 0) { jmin = j; dmin = d; break; }
            int ur = u[r];
            for (auto& e : rows[r]) {
                int jj = e.j;
                if (seen[jj]) continue;
                int nd = d + e.c - ur - v[jj];
                if (nd < dist[jj]) {
                    dist[jj] = nd;
                    pred[jj] = r;
                    heap.emplace_back(nd, jj);
                    std::push_heap(heap.begin(), heap.end(), std::greater<Node>());
                }
            }
        }
        if (jmin < 0) return {};
        int j = jmin;
        while (true) {
            int pr = pred[j];
            int old = col_of_row[pr];
            col_of_row[pr] = j;
            row_of_col[j] = pr;
            int cij = 0;
            for (auto& e : rows[pr]) if (e.j == j) { cij = e.c; break; }
            match_cost[pr] = cij;
            if (pr == i) break;
            j = old;
        }
        for (int jj = 0; jj < n; ++jj) if (seen[jj]) v[jj] += dist[jj] - dmin;
        for (int r = 0; r <= i; ++r) u[r] = match_cost[r] - v[col_of_row[r]];
    }
    return col_of_row;
}

// Dense integer JV
static std::vector<int> jv_dense(const std::vector<int>& cost, int n) {
    const long long INF = (1LL << 60);
    std::vector<long long> u(n + 1), v(n + 1), minv(n + 1);
    std::vector<int> p(n + 1), way(n + 1);
    std::vector<char> used(n + 1);
    for (int i = 1; i <= n; ++i) {
        p[0] = i;
        int j0 = 0;
        std::fill(minv.begin(), minv.end(), INF);
        std::fill(used.begin(), used.end(), 0);
        do {
            used[j0] = 1;
            int i0 = p[j0], j1 = 0;
            long long delta = INF;
            long long ui = u[i0];
            const int* row = cost.data() + (size_t)(i0 - 1) * n;
            for (int j = 1; j <= n; ++j) if (!used[j]) {
                long long cur = (long long)row[j - 1] - ui - v[j];
                if (cur < minv[j]) { minv[j] = cur; way[j] = j0; }
                if (minv[j] < delta) { delta = minv[j]; j1 = j; }
            }
            for (int j = 0; j <= n; ++j) {
                if (used[j]) { u[p[j]] += delta; v[j] -= delta; }
                else minv[j] -= delta;
            }
            j0 = j1;
        } while (p[j0] != 0);
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0);
    }
    std::vector<int> col(n);
    for (int j = 1; j <= n; ++j) col[p[j] - 1] = j - 1;
    return col;
}

static PyObject* solve_dense_int(PyObject* self, PyObject* args) {
    PyObject* cost_obj;
    if (!PyArg_ParseTuple(args, "O", &cost_obj)) return NULL;
    Py_buffer buf;
    if (PyObject_GetBuffer(cost_obj, &buf, PyBUF_SIMPLE)) return NULL;
    int n = (int)std::sqrt((double)(buf.len / sizeof(int32_t)) + 0.5);
    std::vector<int> cost(n * n);
    memcpy(cost.data(), buf.buf, n * n * sizeof(int32_t));
    PyBuffer_Release(&buf);
    auto col = jv_dense(cost, n);
    PyObject* out = PyBytes_FromStringAndSize(nullptr, n * 4);
    memcpy(PyBytes_AS_STRING(out), col.data(), n * 4);
    return out;
}

static PyObject* solve_sparse_int(PyObject* self, PyObject* args) {
    int n;
    PyObject *ei_o, *ej_o, *ec_o;
    if (!PyArg_ParseTuple(args, "iOOO", &n, &ei_o, &ej_o, &ec_o)) return NULL;
    Py_buffer ei_b, ej_b, ec_b;
