// Epsilon-scaling auction, float64 costs, dense row-major.
// Returns col_of_row.

static std::vector<int> auction(const double* cost, int n) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assign(n, -1);
    std::vector<int> unassigned(n);

    double cmin = cost[0], cmax = cost[0];
    for (int i = 0; i < n * n; ++i) {
        double v = cost[i];
        if (v < cmin) cmin = v;
        if (v > cmax) cmax = v;
    }
    double range = cmax - cmin;
    if (range < 1e-15) range = 1e-15;
    // final eps < 1/n of minimum gap. For unique optima of float costs,
    // eps < 1/(n+1) * min positive reduced gap. Use range/(n*n) which
    // matched scipy on random [0,1] in the numba test.
    double final_eps = range / (static_cast<double>(n) * n);
    double eps = range / 2.0;

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int nun = n;
        int guard = 0;
        int max_guard = n * n * 8;
        while (nun > 0 && guard < max_guard) {
            ++guard;
            int i = unassigned[nun - 1];
            const double* row = cost + static_cast<size_t>(i) * n;
            int best_j = 0;
            double best = row[0] + price[0];
            double second = 1e300;
            for (int j = 1; j < n; ++j) {
                double val = row[j] + price[j];
                if (val < best) {
                    second = best;
                    best = val;
                    best_j = j;
                } else if (val < second) {
                    second = val;
                }
            }
            double new_price = second - row[best_j] + eps;
            int old = owner[best_j];
            price[best_j] = new_price;
            owner[best_j] = i;
            assign[i] = best_j;
            if (old != -1) {
                unassigned[nun - 1] = old;
            } else {
                --nun;
            }
        }
        if (eps <= final_eps * 1.0000001) break;
        eps *= 0.25;
        if (eps < final_eps) eps = final_eps;
    }
    return assign;
}

static PyObject* solve(PyObject* self, PyObject* args) {
    PyObject* obj;
    if (!PyArg_ParseTuple(args, "O", &obj)) return NULL;
    Py_buffer buf;
    if (PyObject_GetBuffer(obj, &buf, PyBUF_SIMPLE)) return NULL;
    int n = (int)std::sqrt((double)(buf.len / sizeof(double)) + 0.5);
    auto col = auction((const double*)buf.buf, n);
    PyBuffer_Release(&buf);
    PyObject* out = PyBytes_FromStringAndSize(nullptr, n * 4);
    memcpy(PyBytes_AS_STRING(out), col.data(), n * 4);
    return out;
}

