import time, numpy as np, auction_sp, ot
from scipy.optimize import linear_sum_assignment
from scipy.spatial import cKDTree

def trial(R=0.25, k=None, seeds=6, n=600):
    same_n=0; times=[]; fails=0
    for seed in range(seeds):
        np.random.seed(seed)
        sp=np.random.rand(n,2); tp=np.random.rand(n,2)
        M=ot.dist(sp,tp,metric='euclidean')
        if k is None:
            ii,jj=np.nonzero(M<=R)
            cc=M[ii,jj]
        else:
            tree=cKDTree(tp)
            d,idx=tree.query(sp,k=k)
            ii=np.repeat(np.arange(n),k)
            jj=idx.reshape(-1)
            cc=d.reshape(-1)
        ei=np.ascontiguousarray(ii.astype(np.int32))
        ej=np.ascontiguousarray(jj.astype(np.int32))
        ec=np.ascontiguousarray(cc.astype(np.float64))
        t0=time.perf_counter()
        raw=auction_sp.solve(n, ei, ej, ec, float(M.max()))
        dt=time.perf_counter()-t0
        times.append(dt)
        if raw is None:
            fails += 1
            continue
        col=np.frombuffer(raw,dtype=np.int32)
        r,c=linear_sum_assignment(M)
        same=np.array_equal(col,c)
        same_n += same
        if not same:
            cd=M[np.arange(n),col].sum()-M[r,c].sum()
            print(' mismatch', seed, 'cdiff', cd, 'ndiff', (col!=c).sum())
    print(f'R {R} k {k} avg {np.mean(times):.4f} same {same_n}/{seeds-fails} fails {fails}')

for R in (0.2, 0.25, 0.3, 0.4):
    trial(R=R, seeds=6)
print('knn')
for k in (32, 64, 96):
    trial(k=k, seeds=4)
