// Build radius graph from float64 points n x 2, costs = round(dist * scale)
static PyObject* solve_points(PyObject* self, PyObject* args) {
    PyObject *sp_o, *tp_o;
    double radius, scale;
    if (!PyArg_ParseTuple(args, "OOdd", &sp_o, &tp_o, &radius, &scale)) return NULL;
    Py_buffer sp_b, tp_b;
    if (PyObject_GetBuffer(sp_o, &sp_b, PyBUF_SIMPLE)) return NULL;
    if (PyObject_GetBuffer(tp_o, &tp_b, PyBUF_SIMPLE)) { PyBuffer_Release(&sp_b); return NULL; }
    int n = (int)(sp_b.len / (2 * sizeof(double)));
    const double* sp = (const double*)sp_b.buf;
    const double* tp = (const double*)tp_b.buf;
    double R2 = radius * radius;
    double cell = radius;
    int g = std::max(1, (int)std::ceil(1.0 / cell));
    std::vector<std::vector<int>> bins(g * g);
    auto clamp = [&](int x) { return x < 0 ? 0 : (x >= g ? g - 1 : x); };
    for (int j = 0; j < n; ++j) {
        int ix = clamp((int)(tp[2*j] / cell));
        int iy = clamp((int)(tp[2*j+1] / cell));
        bins[iy * g + ix].push_back(j);
    }
    std::vector<std::vector<Edge>> rows(n);
    long long nedges = 0;
    for (int i = 0; i < n; ++i) {
        double x = sp[2*i], y = sp[2*i+1];
        int ix = clamp((int)(x / cell));
        int iy = clamp((int)(y / cell));
        auto& row = rows[i];
        for (int dy = -1; dy <= 1; ++dy) {
            int yy = iy + dy; if (yy < 0 || yy >= g) continue;
            for (int dx = -1; dx <= 1; ++dx) {
                int xx = ix + dx; if (xx < 0 || xx >= g) continue;
                for (int j : bins[yy * g + xx]) {
                    double dxv = tp[2*j] - x, dyv = tp[2*j+1] - y;
                    double d2 = dxv*dxv + dyv*dyv;
                    if (d2 <= R2) {
                        int c = (int)std::llround(std::sqrt(d2) * scale);
                        row.push_back({j, c});
                    }
                }
            }
        }
        nedges += (long long)row.size();
    }
    auto col = sap_sparse(n, rows);
    PyBuffer_Release(&tp_b); PyBuffer_Release(&sp_b);
    if ((int)col.size() != n) {
        PyErr_Format(PyExc_RuntimeError, "fail edges %lld", nedges);
        return NULL;
    }
    PyObject* bytes = PyBytes_FromStringAndSize(nullptr, n * 4);
    memcpy(PyBytes_AS_STRING(bytes), col.data(), n * 4);
    return Py_BuildValue("(Ni)", bytes, (int)nedges);
}

