#include <Python.h>
#include <vector>
#include <algorithm>
#include <cstdint>
#include <cstring>
#include <cmath>
#include <numeric>

struct Edge { int j; int c; };

// Dial / bucket Dijkstra shortest augmenting path.
// Reduced costs are nonnegative ints. Bucket width 1.
static std::vector<int> sap_sparse(int n, const std::vector<std::vector<Edge>>& rows, int max_cost) {
    const int INF = 0x3fffffff;
    std::vector<int> u(n, 0), v(n, 0);
    std::vector<int> row_of_col(n, -1), col_of_row(n, -1);
    std::vector<int> dist(n), pred(n), match_cost(n, 0);
    std::vector<char> seen(n);

    // circular buckets. Labels can grow; use a large modulo.
    // Worst label is bounded by n * max_cost, but with potentials much smaller.
    // Use a flat vector of buckets sized to max_cost * 2 + 5, and if label exceeds, fall back to scanning.
    int B = std::max(1024, max_cost * 2 + 8);
    std::vector<std::vector<int>> buckets(B);
    for (auto& b : buckets) b.reserve(16);

    for (int i = 0; i < n; ++i) {
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(seen.begin(), seen.end(), 0);
        for (auto& b : buckets) b.clear();

        int ui = u[i];
        int mind = INF;
        for (const auto& e : rows[i]) {
            int rc = e.c - ui - v[e.j];
            if (rc < 0) rc = 0;  // numerical guard
            if (rc < dist[e.j]) {
                dist[e.j] = rc;
                pred[e.j] = i;
                if (rc < B) buckets[rc].push_back(e.j);
                if (rc < mind) mind = rc;
            }
        }
        int jmin = -1, dmin = INF;
        int current = (mind == INF) ? 0 : mind;
        int scanned_empty = 0;
        bool failed = false;
        while (true) {
            if (current >= B) { failed = true; break; }
            auto& b = buckets[current];
            if (b.empty()) {
                ++current;
                if (++scanned_empty > B) { failed = true; break; }
                continue;
            }
            scanned_empty = 0;
            int j = b.back();
            b.pop_back();
            if (seen[j] || dist[j] != current) continue;
            seen[j] = 1;
            int r = row_of_col[j];
            if (r < 0) { jmin = j; dmin = current; break; }
            int ur = u[r];
            for (const auto& e : rows[r]) {
                int jj = e.j;
                if (seen[jj]) continue;
                int nd = current + e.c - ur - v[jj];
                if (nd < 0) nd = 0;
                if (nd < dist[jj]) {
                    dist[jj] = nd;
                    pred[jj] = r;
                    if (nd < B) {
                        buckets[nd].push_back(jj);
                        if (nd < current) current = nd;  // shouldn't happen if nonnegative
                    } else {
                        failed = true;
                    }
                }
            }
            if (failed) break;
        }
        if (failed || jmin < 0) return {};
        int j = jmin;
        while (true) {
            int pr = pred[j];
            int old = col_of_row[pr];
            col_of_row[pr] = j;
            row_of_col[j] = pr;
            int cij = 0;
            for (const auto& e : rows[pr]) if (e.j == j) { cij = e.c; break; }
            match_cost[pr] = cij;
            if (pr == i) break;
            j = old;
        }
        for (int jj = 0; jj < n; ++jj) if (seen[jj]) v[jj] += dist[jj] - dmin;
        for (int r = 0; r <= i; ++r) u[r] = match_cost[r] - v[col_of_row[r]];
    }
    return col_of_row;
}

static PyObject* solve(PyObject* self, PyObject* args) {
    PyObject* cost_obj;
    double thresh, scale;
    if (!PyArg_ParseTuple(args, "Odd", &cost_obj, &thresh, &scale)) return NULL;
    Py_buffer buf;
    if (PyObject_GetBuffer(cost_obj, &buf, PyBUF_SIMPLE)) return NULL;
    int n = (int)std::lround(std::sqrt((double)(buf.len / sizeof(double))));
    const double* M = (const double*)buf.buf;
    int thresh_c = (int)std::llround(thresh * scale);
    std::vector<std::vector<Edge>> rows(n);
    int max_cost = 1;
    for (int i = 0; i < n; ++i) {
        const double* row = M + (size_t)i * n;
        rows[i].reserve(128);
        for (int j = 0; j < n; ++j) {
            double v = row[j];
            if (v <= thresh) {
                int c = (int)std::llround(v * scale);
                if (c > max_cost) max_cost = c;
                rows[i].push_back({j, c});
            }
        }
        if (rows[i].empty()) {
            PyBuffer_Release(&buf);
            Py_RETURN_NONE;
        }
    }
    auto col = sap_sparse(n, rows, max_cost);
    PyBuffer_Release(&buf);
    if ((int)col.size() != n) Py_RETURN_NONE;
    PyObject* out = PyBytes_FromStringAndSize(nullptr, n * 4);
    memcpy(PyBytes_AS_STRING(out), col.data(), n * 4);
    return out;
}

