import time, numpy as np, refine
from reference import Task
task=Task(); n=600
for slack in (2.0, 10.0, 50.0, n):
    times=[]; ok=0; fails=0; edges=[]
    for seed in range(6):
        p=task.generate_problem(n=n, random_seed=seed+11)
        M=np.ascontiguousarray(p['cost_matrix'], dtype=np.float64)
        t0=time.perf_counter()
        out=refine.solve(M, float(slack))
        times.append(time.perf_counter()-t0)
        if out is None:
            fails += 1
            continue
        raw, ne = out
        edges.append(ne)
        col=np.frombuffer(raw, dtype=np.int32)
        G=np.zeros((n,n)); G[np.arange(n), col]=p['source_weights']
        ok += task.is_solution(p, {'transport_plan': G})
    print(f'slack {slack} avg {np.mean(times):.4f} ok {ok}/6 fails {fails} edges {np.mean(edges) if edges else None}')
PY"}
